  return [
    {
      name: 'sales_report',
      description: 'Sum sales amounts between two ISO dates inclusively and return the total plus the number of rows included.',
      inputSchema: SALES_REPORT_SCHEMA
    }
  ];
}

export async function callTool(name, args) {
  if (name !== 'sales_report') {
    throw new Error(`Unknown tool: ${name}`);
  }
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be an object');
  }

  const allowedKeys = new Set(['start_date', 'end_date']);
  for (const key of Object.keys(args)) {
    if (!allowedKeys.has(key)) {
      throw new Error(`Unexpected field: ${key}`);
    }
  }

  const { start_date, end_date } = args;

  if (!isValidIsoDate(start_date)) {
    throw new Error(`Invalid start_date: expected ISO date string YYYY-MM-DD, got ${JSON.stringify(start_date)}`);
  }
  if (!isValidIsoDate(end_date)) {
    throw new Error(`Invalid end_date: expected ISO date string YYYY-MM-DD, got ${JSON.stringify(end_date)}`);
  }
  if (start_date > end_date) {
    throw new Error(`start_date (${start_date}) must be on or before end_date (${end_date})`);
  }

  let total = 0;
  let count = 0;
  for (const row of sales) {
    if (row.date >= start_date && row.date <= end_date) {
      total += row.amount;
      count += 1;
    }
  }

  return {
    content: [
      {
        type: 'text',
        text: `Total ${total} across ${count} row${count === 1 ? '' : 's'}.`
      }
    ]
  };
}

